    params: [{ name: 'owned', kind: 'number', describes: 'ultimate weapons already unlocked, 0 to 9' }],
    returns: { kind: 'number', unit: 'stones', nullable: true, describes: 'the next weapon\'s price' },
    invariants: ['null once all nine are owned', 'null for a count that is not a whole number from 0'],
