    params: [
      { name: 'item', kind: 'string', describes: 'towerTheme, backgroundTheme, song, relic or rotatingRelic' },
      { name: 'rarity', kind: 'string', optional: true, describes: 'Rare or Epic, for the two relic kinds' },
    ],
    returns: { kind: 'object', nullable: true, describes: '{ price, currency: medals|gems }' },
